import pandas as pd

def clean(df):
    df = df.copy()
    # body_mass_g is text with thousands separators (e.g. '4,925'); convert to numeric
    df['body_mass_g'] = df['body_mass_g'].astype(str).str.replace(',', '', regex=False)
    df['body_mass_g'] = pd.to_numeric(df['body_mass_g'], errors='coerce')
    return df

def answer(df):
    df = clean(df)
    result = {}
    grouped = df.groupby('species')['body_mass_g'].sum()
    for species, total in grouped.items():
        if pd.notna(species):
            result[species] = float(total)
    return result
